const a={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Otomatiskan printer Anda dengan aturan JIKA-MAKA yang aman. Nonaktif secara bawaan; aktifkan setiap aturan sendiri."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Belum ada aturan. Tambahkan satu di bawah, lalu aktifkan saat Anda siap."}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"Mesin aturan AKTIF"}},off:{t:0,b:{t:2,i:[{t:3}],s:"Mesin aturan NONAKTIF"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"Aktifkan"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"Nonaktifkan"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"Tidak ada yang berjalan sampai mesin dan aturan masing-masing sama-sama aktif."}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"Saat pencetakan selesai"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"Saat printer mengalami galat"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"Saat heater naik di atas"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"Saat heater turun di bawah"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"Catat notifikasi"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"Jalankan perintah g-code"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"Aktif"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"Nonaktif"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"Sunting"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"Hapus"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"Hapus aturan"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"Nama aturan"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"mis. Matikan heater setelah cetak"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"Jika (pemicu)"}},action:{t:0,b:{t:2,i:[{t:3}],s:"Maka (tindakan)"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"Heater"}},value:{t:0,b:{t:2,i:[{t:3}],s:"Suhu (°C)"}},message:{t:0,b:{t:2,i:[{t:3}],s:"Pesan"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"Ditampilkan di log aturan"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"mis. TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"Simpan aturan"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Batal"}},add:{t:0,b:{t:2,i:[{t:3}],s:"Tambah aturan"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"Aktivitas terbaru"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"diberi tahu"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"menjalankan g-code"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"dilewati (printer sibuk)"}},error:{t:0,b:{t:2,i:[{t:3}],s:"galat"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Panduan"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Panduan mesin aturan"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Tutup"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Apa itu mesin aturan?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Mesin ini memantau printer dan menjalankan tindakan saat kondisi yang Anda atur terpenuhi - misalnya, mencatat catatan saat pencetakan selesai, atau mematikan heater. Setiap aturan berbentuk JIKA (sebuah pemicu) MAKA (sebuah tindakan)."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Cara menjaganya tetap aman"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Mesin nonaktif secara bawaan dan setiap aturan harus diaktifkan satu per satu, sehingga tidak ada yang berjalan secara mendadak. Sebuah aturan dipicu sekali saat kondisinya pertama kali terpenuhi. Tindakan g-code hanya berjalan saat printer diam - tindakan tersebut ditolak selama pencetakan - dan setiap hasilnya dicatat."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glosarium"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"Pemicu"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Kondisi yang memulai sebuah aturan, mis. pencetakan yang selesai atau heater yang melewati suatu suhu."}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"Tindakan"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Apa yang dilakukan aturan saat dipicu: mencatat notifikasi, atau menjalankan perintah g-code (hanya saat diam)."}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"Aktif"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Aturan yang dinyalakan. Aturan yang nonaktif tetap disimpan tetapi tidak pernah dipicu."}}}}}}};export{a as default};
